UPDATE CODELIST c
SET DESCRIPTION = seed.description, LAST_MODIFIED_BY = 'Migration', LAST_MODIFIED_DATE = now()
FROM law_descriptions seed
WHERE c.LIST_NAME = 'NATIONAL_LAW'
  AND c.CODE = seed.code
  AND regexp_replace(
      regexp_replace(btrim(c.DESCRIPTION),
          '^(LOV-|https?://(www\.)?lovdata\.no/(dokument/NL/)?lov/)', '', 'i'),
      '/+$', '') = seed.lovdata_id;
